import{_ as o,o as d,c as t,ag as r}from"./chunks/framework.BaNuf0sO.js";const h=JSON.parse('{"title":"VideoPreviewTrigger（视频预览触发组件）","description":"","frontmatter":{},"headers":[],"relativePath":"docs/core/src/components/modal/docs/README-VideoPreviewTrigger.md","filePath":"docs/core/src/components/modal/docs/README-VideoPreviewTrigger.md"}'),c={name:"docs/core/src/components/modal/docs/README-VideoPreviewTrigger.md"};function a(s,e,i,l,n,g){return d(),t("div",null,[...e[0]||(e[0]=[r(`<h1 id="videopreviewtrigger-视频预览触发组件" tabindex="-1">VideoPreviewTrigger（视频预览触发组件） <a class="header-anchor" href="#videopreviewtrigger-视频预览触发组件" aria-label="Permalink to &quot;VideoPreviewTrigger（视频预览触发组件）&quot;">​</a></h1><blockquote><p>视频触发原语：封面<strong>三形态</strong>——封面图（<code>ElImage</code> 吃原生懒加载）/ 首帧封面（<code>frameCover</code> 默认开，无封面用 <code>video#t=0.01</code> 抠首帧）/ 深色占位（<code>frameCover</code> 关，零请求）——<strong>三形态统一叠加播放图标</strong>（标识可播放）；<strong>默认插槽可整体自定义</strong>（吐 <code>open</code> fn 复用唤起逻辑）；点击经全局遥控器唤起 <code>ModalVideoPreview</code>，无全局则自带弹窗兜底。 与 <code>ImagePreviewTrigger</code> 对等成对（图片触发端点击直达 ElImage 原生预览；视频无 el 原生预览，仍需弹窗决策链）。 范式页：<code>apps/reference/src/pages/modal/preview/showcase/</code></p></blockquote><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><ul><li><strong>何时用</strong>：任意「视频卡片/缩略图可点开播放」场景——上传文件列表、视频素材库；与 <code>ModalVideoPreview</code> 成对（触发端 + 播放端）</li><li><strong>何时不用</strong>：页面内直接播放 → 用 <code>&lt;video&gt;</code> 原生/第三方播放器；仅展示封面不点击 → <code>ElImage</code></li><li>关键机制：<strong>核心 = 唤起预览弹窗的逻辑（决策链 + 自带弹窗兜底）内置</strong>；<strong>默认插槽 = 封面按来源分流 + 播放图标统一</strong>，并吐 <code>open</code> 供自定义内容复用—— <ul><li><strong>有 <code>coverUrl</code></strong> → 落地 <strong><code>ElImage</code></strong>（<code>src=coverUrl</code>）→ <strong>原生 <code>loading=&quot;lazy&quot;</code> 直接可用</strong> + <code>#placeholder</code>/<code>#error</code> 占位兜底，<strong>封面图上叠加播放图标</strong>（有播放按钮就知道是啥——三形态统一标识可播放）；</li><li><strong>无 <code>coverUrl</code> · <code>frameCover</code> 开（默认）</strong> → 落地 <strong><code>&lt;video :src=&quot;url#t=0.01&quot; preload=&quot;metadata&quot;&gt;</code></strong>——Media Fragments 定位 0.01s 渲染<strong>首帧当封面</strong> + 播放图标叠加；<code>preload=&quot;metadata&quot;</code> 只拉元数据 + 首帧所在分片（<strong>不拉全片</strong>）；</li><li><strong>无 <code>coverUrl</code> · <code>frameCover</code> 关</strong> → <strong>深色占位底 + 播放图标</strong>——零请求零副作用（无需封面的素材库 / 纯占位场景）</li></ul></li><li><strong>默认插槽可整体自定义</strong>：<code>#default=&quot;{ open }&quot;</code> 接自定义内容（如按钮「播放」）——<code>open</code> = 唤起预览的 fn（内部决策链 + 自带弹窗兜底不变），组件不关心自定义内容形态；缺省用内置封面/占位 + 播放图标</li><li><strong>点击决策链（全局优先，自带兜底）</strong>：<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if (remote?.value?.modalKey?.includes(APP_GLOBAL_VIDEO_PREVIEW_KEY)) {</span></span>
<span class="line"><span>  remote.value[APP_GLOBAL_VIDEO_PREVIEW_KEY].evoke({ url, coverUrl });  // 全局遥控唤起</span></span>
<span class="line"><span>} else {</span></span>
<span class="line"><span>  localShow = true;                                                     // 自带 ModalVideoPreview 兜底（v-if）</span></span>
<span class="line"><span>}</span></span></code></pre></div><code>remote</code> = <code>inject(GLOBAL_MODAL_REMOTE_KEY)</code>（core 导出注入 key，消费方 App 根 provide 同一对象；未注入/未注册 → 静默回退自带弹窗，任何环境可用）</li><li><strong><code>modalKey</code> 存在性判断</strong>：遥控器对象上的 <code>modalKey: string[]</code>（架子 <code>registerConfig</code> 同步维护）——<code>includes(全局 key)</code> 显式判断，不依赖 <code>evoke</code> 返回值（evoke 无返回值，未注册直接调会 TypeError）</li></ul><h2 id="快速上手-最小可用" tabindex="-1">快速上手（最小可用） <a class="header-anchor" href="#快速上手-最小可用" aria-label="Permalink to &quot;快速上手（最小可用）&quot;">​</a></h2><div class="language-vue vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">VideoPreviewTrigger</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://example.com/a.mp4&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><p><strong>要点</strong>：</p><ul><li><code>url</code> 必传（视频地址）；无封面默认走 <strong><code>frameCover</code> 首帧封面</strong>（<code>#t=0.01</code> + <code>preload=&quot;metadata&quot;</code>——只拉元数据 + 首帧，不拉全片）</li><li>有封面：<code>coverUrl</code> 传封面图 → 缩略图吃原生懒加载</li><li>不想要首帧请求：<code>:frame-cover=&quot;false&quot;</code> → 回退深色占位（<strong>零请求</strong>，连 metadata 都不拉）</li><li>点击后：AppLayout 开了 <code>enableGlobalVideoPreview</code>（全局 key 已注册）→ 全局遥控唤起；否则组件自带 <code>ModalVideoPreview</code> 本地弹窗</li></ul><h2 id="能力边界-按需使用" tabindex="-1">能力边界 / 按需使用 <a class="header-anchor" href="#能力边界-按需使用" aria-label="Permalink to &quot;能力边界 / 按需使用&quot;">​</a></h2><ul><li><strong>默认即够用：封面/占位 + 播放图标 + 点击弹播放</strong>——绝大多数场景只传 <code>url</code>。</li><li><code>coverUrl</code>：仅当业务有封面图（如上传时单独传了封面）时传——有封面走 img 路径白拿懒加载 + 图标叠加。</li><li><code>frameCover</code>（默认 <code>true</code>）：无 <code>coverUrl</code> 时是否用 <code>video#t=0.01</code> 抠首帧作封面——开 = 首帧封面（视觉接近封面图，代价是<strong>每实例一个 metadata 小请求</strong>，<code>video</code> 无原生 lazy）；关 = 深色占位（<strong>零请求</strong>）。视频素材库大列表介意请求量 → 关掉或按需补懒加载（YAGNI，暂未内置）。</li><li><strong><code>#default=&quot;{ open }&quot;</code></strong>：整体自定义触发 UI（按钮 / 卡片 / 列表行）——<code>open</code> 即「打开预览弹窗」，核心决策链与兜底不变；<code>placeholder</code> / <code>error</code> 插槽仅内置封面内容使用。</li><li><strong>点击不冒泡（仅 <code>preview</code> 开启时）</strong>：唤起预览的同时 <code>stopPropagation</code>——封面常嵌在表格行 / 卡片里，点封面看视频 [MUST NOT] 连带触发行点击 / 卡片跳转。<code>preview={false}</code>（纯展示）<strong>不拦</strong>，事件照常上抛。 <strong>自定义默认插槽同样受益</strong>：<code>open</code> 接收事件对象，<code>#default=&quot;{ open }&quot;</code> 里写 <code>@click=&quot;open&quot;</code> 即自动阻止冒泡（写成 <code>@click=&quot;() =&gt; open()&quot;</code> 丢掉事件则不阻止，需自行 <code>.stop</code>）。</li><li>弹窗端行为（<code>coverUrl</code> 为空时 <code>#t=0.01</code> 首帧兜底等）在 <code>ModalVideoPreview</code> 上，见 README-ModalVideoPreview——<strong>触发端首帧由 <code>frameCover</code> 控制</strong>。</li><li><strong>完整能力演示</strong>：<code>apps/reference/src/pages/modal/preview/showcase/</code>——能力展示，非推荐默认。</li></ul><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><blockquote><p>⚠️ API 以 types.ts 与组件源码为真相源；与文档冲突时以源码为准。</p></blockquote><h3 id="props-内联-defineprops-无-types-ts" tabindex="-1">Props（内联 defineProps，无 types.ts） <a class="header-anchor" href="#props-内联-defineprops-无-types-ts" aria-label="Permalink to &quot;Props（内联 defineProps，无 types.ts）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>name</th><th>type</th><th>默认</th><th>语义</th></tr></thead><tbody><tr><td><code>url</code></td><td><code>string</code>（必传）</td><td>—</td><td>视频地址（点击唤起预览弹窗的视频）</td></tr><tr><td><code>coverUrl</code></td><td><code>string</code></td><td>—</td><td>封面图地址；<strong>空 → 首帧封面（<code>frameCover</code> 默认开）或深色占位（关）</strong>；有 → ElImage 封面（原生懒加载）</td></tr><tr><td><code>frameCover</code></td><td><code>boolean</code></td><td><code>true</code></td><td>无 <code>coverUrl</code> 时用 <code>video#t=0.01</code> 首帧作封面（<code>preload=&quot;metadata&quot;</code> 只拉元数据 + 首帧，不拉全片）；关 = 深色占位 + 播放图标（零请求）</td></tr><tr><td><code>lazy</code></td><td><code>boolean</code></td><td><code>true</code></td><td>封面图懒加载（仅 <code>coverUrl</code> 有值时生效）</td></tr><tr><td><code>preview</code></td><td><code>boolean</code></td><td><code>true</code></td><td>是否可点击唤起预览（false = 纯展示封面/占位）</td></tr></tbody></table><blockquote><p><strong>img 原生属性全量透传</strong>：<code>$attrs</code> 直达自身 ElImage（<code>coverUrl</code> 路径）——<code>alt</code> / <code>fit</code> / <code>loading</code> 等均可用。 ⚠ <strong><code>width</code> / <code>height</code> 无效</strong>：EP 2.13 的 ElImage 未声明 width/height props，透传会落根 div 的 HTML attribute（对 div 无渲染效果）。尺寸控制请用外层 CSS / <code>style</code>（配合 <code>fit=&quot;cover&quot;</code> 居中裁切）。</p></blockquote><h3 id="emits" tabindex="-1">Emits <a class="header-anchor" href="#emits" aria-label="Permalink to &quot;Emits&quot;">​</a></h3><p>无</p><h3 id="slots" tabindex="-1">Slots <a class="header-anchor" href="#slots" aria-label="Permalink to &quot;Slots&quot;">​</a></h3><table tabindex="0"><thead><tr><th>槽</th><th>scope</th><th>语义</th></tr></thead><tbody><tr><td><code>#default</code></td><td><code>{ open: (event?: Event) =&gt; void }</code></td><td><strong>可整体自定义触发 UI</strong>（按钮「播放」/卡片/列表行）：<code>open</code> = 打开预览弹窗（内部决策链 + 自带兜底不变）；缺省 = 封面图/占位 + 播放图标（两形态统一），自带点击唤起</td></tr><tr><td><code>#placeholder</code></td><td>无</td><td>封面加载中占位（透传 ElImage；仅内置封面内容）</td></tr><tr><td><code>#error</code></td><td>无</td><td>封面加载失败兜底图（透传 ElImage；仅内置封面内容）</td></tr></tbody></table><h3 id="expose" tabindex="-1">Expose <a class="header-anchor" href="#expose" aria-label="Permalink to &quot;Expose&quot;">​</a></h3><p>无</p><h2 id="反模式-注意" tabindex="-1">反模式 / 注意 <a class="header-anchor" href="#反模式-注意" aria-label="Permalink to &quot;反模式 / 注意&quot;">​</a></h2><ul><li><strong><code>frameCover</code> 默认开会发请求</strong>：无封面首帧封面 = 每实例一个 metadata 小请求（<strong>非零请求</strong>）；素材库大列表（几十个）首帧渲染会同时发 N 个小请求（单个体量极小，但 <code>video</code> 无原生 lazy）。介意请求量 → <code>:frame-cover=&quot;false&quot;</code> 回退零请求占位，或按需补 IntersectionObserver 懒加载（YAGNI，暂未内置）</li><li><strong>Safari/iOS <code>#t</code> 兼容薄弱</strong>：Media Fragments 时间片做首帧在移动端 Safari 历史上不可靠（现代版本基本可用）；若目标用户强 iOS，可 <code>:frame-cover=&quot;false&quot;</code> 走占位或业务侧自行传 <code>coverUrl</code></li><li><strong><code>$attrs</code> 只落封面层</strong>：想配「弹窗端视频」（<code>autoplay</code> / <code>muted</code> 等）[MUST NOT] 经触发组件透传——去 <code>ModalVideoPreview</code> 上配</li><li><strong>决策链静默回退是硬行为</strong>：任何环境（无遥控器/未注册/未开启全局）都不许报错——自带弹窗兜底保证触发组件永远可用</li><li><strong><code>preview=false</code> 只关点击</strong>：仍渲染封面/占位——「展示」能力不随「预览」关掉</li><li><strong><code>open</code> 要把事件透给它</strong>：<code>#default=&quot;{ open }&quot;</code> 里写 <code>@click=&quot;open&quot;</code>（自动阻止冒泡）优于 <code>@click=&quot;() =&gt; open()&quot;</code>（丢事件 → 不阻止冒泡，外层行点击被连带触发）</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>播放端：<code>ModalVideoPreview</code>（视频预览弹窗，ModalConfirm 为底 + url/coverUrl，封面空 <code>#t=0.01</code> 首帧兜底）</li><li>对等组件：<code>ImagePreviewTrigger</code>（图片触发端，同一决策链；ElImage 落地 + previewSrc 原图）</li><li>全局遥控：<code>GlobalModalRemote</code> / <code>GlobalModalControl</code> / <code>modalKey</code>（modal-shelf-types）+ 注入 key <code>GLOBAL_MODAL_REMOTE_KEY</code>（core 导出）+ 全局 key 常量 <code>APP_GLOBAL_VIDEO_PREVIEW_KEY</code></li><li>AppLayout 开关：<code>enableGlobalVideoPreview</code>（开启后自动注册全局视频预览弹窗，见 README-AppLayout）</li><li>范式页：<code>apps/reference/src/pages/modal/preview/showcase/</code></li></ul>`,25)])])}const u=o(c,[["render",a]]);export{h as __pageData,u as default};
